// Nemecký preklad manuálu v Pomoci (src/routes/pomoc.doklady.tsx). Kľúče vyrába pomoc-preklad.test.tsx.
export default {
  "Pomoc — Doklady a skenovanie — Faktero": "Hilfe — Belege und Scannen — Faktero",
  "Doklady vo Faktere: odfotenie bločku, načítanie eKasa QR kódu z Finančnej správy, nahratie PDF, presun medzi prijaté faktúry a odovzdanie účtovníčke.":
    "Belege in Faktero: Kassenbon fotografieren, eKasa-QR-Code der Finanzverwaltung (Finančná správa) einlesen, PDF hochladen, in Eingangsrechnungen verschieben und an die Buchhalterin übergeben.",
  "Pomoc · Doklady": "Hilfe · Belege",
  "Doklady a skenovanie": "Belege und Scannen",
  "Bločky a drobné výdavky — odfotené, načítané z eKasa QR kódu alebo nahraté ako PDF, vždy pripravené pre účtovníčku.":
    "Kassenbons und Kleinausgaben — fotografiert, aus dem eKasa-QR-Code eingelesen oder als PDF hochgeladen, immer bereit für die Buchhalterin.",
  "Nespracované doklady — všetko najprv sem": "Unverarbeitete Belege — alles landet zuerst hier",
  "Všetko, čo príde <0>e-mailom</0> alebo čo <1>nahráte</1> (tlačidlo Nahrať faktúru, appka, pretiahnutie súborov), čaká najprv v <2>Doklady → Nespracované doklady</2>. Faktero doklad prečíta a navrhne, čo to je. Kým je doklad tu, nevstupuje do DPH, pokladne ani do účtovníctva.":
    "Alles, was <0>per E-Mail</0> eingeht oder was Sie <1>hochladen</1> (Schaltfläche Rechnung hochladen, App, Dateien hineinziehen), wartet zuerst unter <2>Belege → Unverarbeitete Belege</2>. Faktero liest den Beleg aus und schlägt vor, worum es sich handelt. Solange der Beleg hier liegt, fließt er weder in die MwSt. noch in die Kasse oder die Buchhaltung ein.",
  "<0>Bloček s QR kódom</0> (eKasa) ide rovno do <1>Bločkov</1> — údaje sú z Finančnej správy. Kto chce aj tieto kontrolovať, zapne v Účtovníctvo → Predkontácie voľbu „Bločky s QR kódom ukladať do Nespracovaných dokladov“.":
    "<0>Kassenbon mit QR-Code</0> (eKasa) geht direkt in die <1>Kassenbons</1> — die Daten stammen von der Finanzverwaltung. Wer auch diese prüfen möchte, aktiviert unter Buchhaltung → Vorkontierungen die Option „Kassenbons mit QR-Code in Unverarbeitete Belege speichern“.",
  "<0>Bloček bez QR</0> (fotka, parkovanie, zahraničný), <1>faktúra</1>, <2>zálohová faktúra</2> a <3>iný doklad</3> z appky, nahratie na webe aj doklad z e-mailu idú do Nespracovaných dokladov.":
    "<0>Kassenbon ohne QR</0> (Foto, Parken, Ausland), <1>Rechnung</1>, <2>Anzahlungsrechnung</2> und <3>sonstiger Beleg</3> aus der App, Uploads im Web sowie Belege aus E-Mails gehen in die Unverarbeiteten Belege.",
  "Po kliknutí na <0>Vytvoriť</0> sa doklad presunie do Bločkov, Prijatých faktúr alebo Iných dokladov podľa druhu.":
    "Nach einem Klick auf <0>Erstellen</0> wird der Beleg je nach Art in die Kassenbons, Eingangsrechnungen oder Sonstigen Belege verschoben.",
  "Kliknite na doklad — vľavo uvidíte samotný doklad, vpravo vyťažené údaje.":
    "Klicken Sie auf einen Beleg — links sehen Sie den Beleg selbst, rechts die ausgelesenen Daten.",
  "Vyberte <0>druh dokladu</0>: prijatá faktúra, zálohová faktúra, dobropis, bloček alebo iný doklad (zmluva, list, predpis).":
    "Wählen Sie die <0>Belegart</0>: Eingangsrechnung, Anzahlungsrechnung, Gutschrift, Kassenbon oder sonstiger Beleg (Vertrag, Schreiben, Bescheid).",
  "Skontrolujte údaje. Povinné polia, ktoré chýbajú, sú <0>červené</0> — pri faktúre číslo a splatnosť, pri bločku spôsob úhrady, pri dobropise opravovaná faktúra.":
    "Prüfen Sie die Daten. Fehlende Pflichtfelder sind <0>rot</0> — bei einer Rechnung Nummer und Fälligkeit, beim Kassenbon die Zahlungsart, bei einer Rechnungskorrektur die korrigierte Rechnung.",
  "Kontroly, položky, zamknutie a história": "Prüfungen, Positionen, Sperre und Verlauf",
  "Pri spracovaní Faktero upozorní, keď doklad <0>už v evidencii je</0> (rovnaké číslo od toho istého dodávateľa), keď je faktúra vystavená na <1>inú firmu</1>, a keď je splatnosť skôr ako dátum vystavenia. Tlačidlo <2>Dočítať z dokladu</2> doplní chýbajúce údaje (VS, IBAN, splatnosť, adresu) bez prepísania vyplnených.":
    "Bei der Verarbeitung weist Faktero darauf hin, wenn ein Beleg <0>bereits erfasst ist</0> (gleiche Nummer vom selben Lieferanten), wenn die Rechnung auf ein <1>anderes Unternehmen</1> ausgestellt ist und wenn die Fälligkeit vor dem Rechnungsdatum liegt. Die Schaltfläche <2>Aus Beleg nachlesen</2> ergänzt fehlende Daten (VS, IBAN, Fälligkeit, Adresse), ohne bereits ausgefüllte zu überschreiben.",
  "Keď sú položky vyčítané úplne zle, stlačte <0>Vypnúť položky</0>. Doklad sa potom vytvorí a zaúčtuje len podľa súčtov a rozpisu DPH — rozúčtovanie, export do Pohody aj výkazy k DPH položky nepoužijú. To isté tlačidlo je aj v detaile prijatej faktúry a položky sa ním dajú kedykoľvek vrátiť.":
    "Wenn die Positionen völlig falsch ausgelesen wurden, klicken Sie auf <0>Positionen deaktivieren</0>. Der Beleg wird dann nur anhand der Summen und der MwSt.-Aufschlüsselung erstellt und verbucht — Aufteilung, Export nach Pohoda und MwSt.-Meldungen verwenden die Positionen nicht. Dieselbe Schaltfläche gibt es auch im Detail der Eingangsrechnung; damit lassen sich die Positionen jederzeit wiederherstellen.",
  "Prijatú faktúru aj bloček môžete <0>zamknúť</0> — sumy, dátumy ani zaúčtovanie sa potom nedajú meniť, kým ho neodomknete. Doklad odovzdaný do účtovníctva je zamknutý vždy. Zle zaradenú prijatú faktúru vrátite tlačidlom <1>Vrátiť do Nespracovaných</1>.":
    "Eingangsrechnungen und Kassenbons können Sie <0>sperren</0> — Beträge, Daten und Kontierung lassen sich dann nicht ändern, bis Sie sie wieder entsperren. Ein an die Buchhaltung übergebener Beleg ist immer gesperrt. Eine falsch zugeordnete Eingangsrechnung schicken Sie mit der Schaltfläche <1>Zurück in Unverarbeitete</1> zurück.",
  "Na detaile dokladu je <0>história zmien</0> (kto, kedy a čo zmenil) a <1>štítky</1> — najviac päť vlastných značiek na triedenie. V komentári označíte kolegu napísaním <2>@meno</2>; dostane upozornenie do zvončeka. Iné doklady sa dajú triediť do <3>priečinkov</3>.":
    "Im Belegdetail finden Sie den <0>Änderungsverlauf</0> (wer hat wann was geändert) und <1>Tags</1> — höchstens fünf eigene Markierungen zum Sortieren. Im Kommentar erwähnen Sie Kollegen mit <2>@Name</2>; sie erhalten eine Benachrichtigung in der Glocke. Sonstige Belege lassen sich in <3>Ordner</3> einsortieren.",
  "Čo sú Doklady a čím sa líšia od prijatých faktúr":
    "Was sind Belege und wie unterscheiden sie sich von Eingangsrechnungen",
  "<0>Doklady</0> sú drobné výdavky, ktoré nemajú faktúru — bločky z čerpačky, z obchodu, z parkoviska, účtenky z reštaurácie. Odfotíte ich hneď na mieste a účtovníčka ich má na konci mesiaca pokope.":
    "<0>Belege</0> sind Kleinausgaben ohne Rechnung — Kassenbons von der Tankstelle, aus dem Geschäft, vom Parkplatz, Quittungen aus dem Restaurant. Sie fotografieren sie gleich vor Ort, und die Buchhalterin hat sie am Monatsende gesammelt beisammen.",
  "<0>Prijaté faktúry</0> sú naproti tomu doklady so splatnosťou, ktoré niekomu dlžíte. Ak sa z bločku vykľuje faktúra, netreba ju prepisovať — pozri <1>Presun medzi prijaté faktúry</1>.":
    "<0>Eingangsrechnungen</0> sind dagegen Belege mit Fälligkeit, bei denen Sie jemandem etwas schulden. Stellt sich ein Kassenbon als Rechnung heraus, müssen Sie ihn nicht abtippen — siehe <1>In Eingangsrechnungen verschieben</1>.",
  "Tri spôsoby, ako doklad dostať dnu": "Drei Wege, einen Beleg zu erfassen",
  "V <0>Doklady → Nový doklad</0> máte tri tlačidlá:":
    "Unter <0>Belege → Neuer Beleg</0> gibt es drei Schaltflächen:",
  "<0>Odfotiť</0> — fotku prečíta AI a doplní dodávateľa, dátum, sumu, sadzby DPH aj jednotlivé položky.":
    "<0>Fotografieren</0> — die KI liest das Foto aus und ergänzt Lieferant, Datum, Betrag, MwSt.-Sätze sowie die einzelnen Positionen.",
  "<0>QR kód</0> — naskenuje eKasa QR z bločku. To je najpresnejšia cesta, viac nižšie.":
    "<0>QR-Code</0> — scannt den eKasa-QR-Code vom Kassenbon. Das ist der genaueste Weg, mehr dazu unten.",
  "<0>Nahrať súbor</0> — fotka alebo PDF z počítača. Súbor sa dá aj pretiahnuť myšou do vyznačenej plochy.":
    "<0>Datei hochladen</0> — Foto oder PDF vom Computer. Die Datei lässt sich auch mit der Maus in den markierten Bereich ziehen.",
  "Po načítaní sa formulár vyplní sám, ale <0>zostáva na vás ho skontrolovať</0>. Doplňte kategóriu (napríklad „pohonné hmoty“), spôsob platby — hotovosťou, kartou alebo prevodom — a prípadne poznámku.":
    "Nach dem Einlesen füllt sich das Formular selbst aus, <0>die Prüfung bleibt aber Ihre Aufgabe</0>. Ergänzen Sie die Kategorie (zum Beispiel „Kraftstoffe“), die Zahlungsart — bar, Karte oder Überweisung — und ggf. eine Notiz.",
  "eKasa QR kód": "eKasa-QR-Code",
  "QR kód na slovenskom bločku nenesie sumu ani položky — nesie <0>identifikátor dokladu (UID)</0>. Faktero si s ním vypýta celý doklad priamo z Finančnej správy, takže sa načíta presne to, čo predajca odoslal: dodávateľ, IČO, dátum, čas, položky aj rozpis DPH.":
    "Der QR-Code auf einem slowakischen Kassenbon enthält weder Betrag noch Positionen — er enthält die <0>Belegkennung (UID)</0>. Damit fordert Faktero den vollständigen Beleg direkt bei der Finanzverwaltung an; eingelesen wird also genau das, was der Verkäufer übermittelt hat: Lieferant, Firmen-ID (IČO), Datum, Uhrzeit, Positionen und MwSt.-Aufschlüsselung.",
  "Podľa toho, ako sa doklad podarilo získať, svieti nad formulárom štítok:":
    "Je nachdem, wie der Beleg ermittelt wurde, erscheint über dem Formular ein Hinweis:",
  "<0>✓ Načítané z Finančnej správy</0> — údaje sú overené, netreba ich kontrolovať.":
    "<0>✓ Von der Finanzverwaltung geladen</0> — die Daten sind verifiziert und müssen nicht geprüft werden.",
  "<0>Len z QR kódu</0> — doklad sa vo Finančnej správe nenašiel (stáva sa pri čerstvých bločkoch alebo pri výpadku ich systému). Suma z QR kódu sedí, položky chýbajú.":
    "<0>Nur aus QR-Code</0> — der Beleg wurde bei der Finanzverwaltung nicht gefunden (kommt bei ganz neuen Kassenbons oder bei einem Ausfall ihres Systems vor). Der Betrag aus dem QR-Code stimmt, die Positionen fehlen.",
  "<0>Odhadnuté z fotky</0> — QR sa nedal prečítať a údaje odhadla AI. <1>Tie si prejdite</1>.":
    "<0>Aus Foto geschätzt</0> — der QR-Code war nicht lesbar und die Daten hat die KI geschätzt. <1>Prüfen Sie diese</1>.",
  "Doklady a pokladňa": "Belege und Kasse",
  "Ak dáte spôsob platby <0>hotovosťou</0>, doklad automaticky uberie z hotovosti v <1>pokladni</1> — nemusíte k nemu robiť ešte aj výdavkový pokladničný doklad. Podrobne v <2>manuáli k pokladni</2>.":
    "Wählen Sie als Zahlungsart <0>bar</0>, mindert der Beleg automatisch den Bargeldbestand in der <1>Kasse</1> — einen zusätzlichen Kassenausgangsbeleg brauchen Sie nicht. Details im <2>Handbuch zur Kasse</2>.",
  "Doklad platený kartou alebo prevodom stav pokladne nemení.":
    "Ein mit Karte oder per Überweisung bezahlter Beleg ändert den Kassenbestand nicht.",
  "Presun medzi prijaté faktúry": "In Eingangsrechnungen verschieben",
  "Keď sa ukáže, že nahratý doklad je v skutočnosti faktúra so splatnosťou, presuniete ho jedným tlačidlom na riadku v zozname dokladov. Prenesie sa aj s prílohou a <0>z Dokladov zmizne</0> — aby sa ten istý náklad nepočítal dvakrát.":
    "Stellt sich heraus, dass ein hochgeladener Beleg tatsächlich eine Rechnung mit Fälligkeit ist, verschieben Sie ihn mit einer Schaltfläche in der Zeile der Belegliste. Er wird samt Anhang übernommen und <0>verschwindet aus den Belegen</0> — damit derselbe Aufwand nicht doppelt gezählt wird.",
  "Iné doklady — listy, predpisy, exekúcie": "Sonstige Belege — Schreiben, Bescheide, Pfändungen",
  "Nie všetko, z čoho účtovník účtuje, je faktúra alebo bloček. Exekučný príkaz, predpis poistného, list z daňového úradu či zmluvu nahráte do <0>Doklady → Iné doklady</0>. Vyberiete druh dokladu, odosielateľa, dátum doručenia a pripojíte PDF alebo fotky (aj viac strán). Suma a lehota sú nepovinné — lehota, ktorá sa blíži alebo už uplynula, sa v zozname zvýrazní.":
    "Nicht alles, was der Buchhalter verbucht, ist eine Rechnung oder ein Kassenbon. Einen Pfändungsbeschluss, einen Beitragsbescheid, ein Schreiben vom Finanzamt oder einen Vertrag laden Sie unter <0>Belege → Sonstige Belege</0> hoch. Sie wählen die Belegart, den Absender und das Zustelldatum und hängen ein PDF oder Fotos an (auch mehrseitig). Betrag und Frist sind optional — eine nahende oder bereits abgelaufene Frist wird in der Liste hervorgehoben.",
  "Údaje nemusíte prepisovať: po pridaní prílohy ju prečíta <0>AI</0> a doplní druh, odosielateľa, predmet, sumu, lehotu aj krátke zhrnutie pre účtovníka. V mobilnej appke je na skeneri voľba <1>Iný doklad</1> — nafotíte strany a doklad sa uloží sem. A keď takýto dokument príde na adresu pre <2>doklady e-mailom</2>, AI ho rozpozná a uloží medzi ostatné doklady namiesto prijatých faktúr.":
    "Sie müssen nichts abtippen: Nach dem Hinzufügen eines Anhangs liest ihn die <0>KI</0> aus und ergänzt Art, Absender, Betreff, Betrag, Frist sowie eine kurze Zusammenfassung für den Buchhalter. In der mobilen App gibt es im Scanner die Option <1>Sonstiger Beleg</1> — Sie fotografieren die Seiten, und der Beleg wird hier gespeichert. Und wenn ein solches Dokument an die Adresse für <2>Belege per E-Mail</2> geschickt wird, erkennt die KI es und legt es unter den Sonstigen Belegen statt unter den Eingangsrechnungen ab.",
  "<0>Exekúciu</0> priradíte k zamestnancovi — AI ho navrhne sama, keď v dokumente nájde jeho celé meno — a na karte zamestnanca ju uvidíte v záložke <1>Exekúcie</1>. Doklad k leasingu či úveru priradíte k zmluve a nájdete ho v jej detaile v časti <2>Doklady k zmluve</2>. Na lehotu, ktorá príde do siedmich dní alebo už uplynula, upozorní zvonček, kým doklad neodovzdáte účtovníkovi.":
    "Eine <0>Pfändung</0> ordnen Sie einem Mitarbeiter zu — die KI schlägt ihn selbst vor, wenn sie im Dokument seinen vollständigen Namen findet — und auf der Mitarbeiterkarte sehen Sie sie im Reiter <1>Pfändungen</1>. Einen Beleg zu Leasing oder Kredit ordnen Sie dem Vertrag zu und finden ihn in dessen Detail im Bereich <2>Belege zum Vertrag</2>. Auf eine Frist, die in sieben Tagen abläuft oder bereits abgelaufen ist, weist die Glocke hin, bis Sie den Beleg an den Buchhalter übergeben.",
  "Aj tu platí <0>Nespracované → Spracované → Odovzdané</0>: účtovník doklad pozrie a klikne na <1>Spracovať</1>. Iné doklady sa do Pohody neposielajú, sú podkladom. V mesačnom balíku pre účtovníka sú v priečinku <2>ostatne-doklady</2> so súpisom v CSV.":
    "Auch hier gilt <0>Unverarbeitet → Verarbeitet → Übergeben</0>: Der Buchhalter sieht sich den Beleg an und klickt auf <1>Verarbeiten</1>. Sonstige Belege werden nicht an Pohoda gesendet, sie dienen als Unterlage. Im Monatspaket für den Buchhalter liegen sie im Ordner <2>ostatne-doklady</2> mit einer Aufstellung als CSV.",
  "Prechod z Doklado — import prijatých dokladov":
    "Umstieg von Doklado — Import von Eingangsbelegen",
  "V <0>Účtovníctvo → Import prijatých dokladov</0> nahráte export z Doklado, Pohody alebo tabuľku. Najpresnejšie je nahrať naraz <1>XML (Pohoda)</1> a <2>ZIP s PDF</2>: údaje sa vezmú z XML a skeny sa priradia k dokladom podľa čísla, alebo podľa sumy, dátumu a dodávateľa. Ide aj <3>CSV/XLSX</3> a samotný ZIP so skenmi — ten prečíta AI.":
    "Unter <0>Buchhaltung → Import von Eingangsbelegen</0> laden Sie einen Export aus Doklado, Pohoda oder eine Tabelle hoch. Am genauesten ist es, <1>XML (Pohoda)</1> und <2>ZIP mit PDFs</2> zusammen hochzuladen: Die Daten werden aus dem XML übernommen, und die Scans werden den Belegen anhand der Nummer oder anhand von Betrag, Datum und Lieferant zugeordnet. Auch <3>CSV/XLSX</3> und ein reines ZIP mit Scans sind möglich — dieses liest die KI aus.",
  "Prijaté faktúry pôjdu medzi prijaté faktúry, bločky do Dokladov a listy, predpisy či exekúcie do Iných dokladov. Pred spustením uvidíte, čo sa naimportuje, a zvolíte stav (napríklad „Odovzdané účtovníkovi“ pre doklady, ktoré sú už zaúčtované). Doklady, ktoré vo Fakteri už sú, sa preskočia, takže import sa dá pustiť aj opakovane. Hotovostné bločky sa do pokladne započítajú len vtedy, keď to zaškrtnete.":
    "Eingangsrechnungen landen bei den Eingangsrechnungen, Kassenbons bei den Belegen und Schreiben, Bescheide oder Pfändungen bei den Sonstigen Belegen. Vor dem Start sehen Sie, was importiert wird, und wählen den Status (zum Beispiel „An Buchhalter übergeben“ für bereits verbuchte Belege). Belege, die bereits in Faktero vorhanden sind, werden übersprungen, sodass sich der Import auch wiederholt ausführen lässt. Barzahlungs-Kassenbons werden nur dann in die Kasse eingerechnet, wenn Sie dies ankreuzen.",
  "Zoznam, filtre a odovzdanie účtovníčke": "Liste, Filter und Übergabe an die Buchhalterin",
  "Každý nový doklad — z appky, z webu aj naskenovaný — padne najprv do záložky <0>Nespracované</0>. Tam ho vy alebo účtovník skontrolujete, prípadne doplníte a kliknete na <1>Spracovať</1> (viac naraz cez zaškrtnutie a <2>Označiť ako spracované</2>). Spracovať sa dá doklad so sumou a dátumom; ak niečo chýba, zoznam to napíše a ponúkne <3>Doplniť</3>.":
    "Jeder neue Beleg — aus der App, aus dem Web oder gescannt — landet zuerst im Reiter <0>Unverarbeitet</0>. Dort prüfen Sie oder der Buchhalter ihn, ergänzen ggf. Angaben und klicken auf <1>Verarbeiten</1> (mehrere auf einmal per Häkchen und <2>Als verarbeitet markieren</2>). Verarbeiten lässt sich ein Beleg mit Betrag und Datum; fehlt etwas, zeigt die Liste es an und bietet <3>Ergänzen</3> an.",
  "Ďalšie záložky sú <0>Spracované</0>, <1>Odovzdané účtovníkovi</1> a <2>Všetky</2>, filtrujú sa podľa mesiaca. Nespracované sa ukazujú zo všetkých mesiacov, aby žiadny neostal schovaný. Prepojenie s Pohodou si berie len spracované doklady. Pri každom doklade vidno dátum, dodávateľa, sumu a <3>zdroj</3> — teda či prišiel z eKasy, z fotky alebo bol nahratý ručne.":
    "Weitere Reiter sind <0>Verarbeitet</0>, <1>An Buchhalter übergeben</1> und <2>Alle</2>; sie werden nach Monat gefiltert. Unverarbeitete werden aus allen Monaten angezeigt, damit keiner verborgen bleibt. Die Anbindung an Pohoda übernimmt nur verarbeitete Belege. Bei jedem Beleg sehen Sie Datum, Lieferant, Betrag und <3>Quelle</3> — also ob er aus eKasa, von einem Foto stammt oder manuell hochgeladen wurde.",
  "Nad zoznamom je <0>Hľadať</0> (dodávateľ, IČO, číslo dokladu) a filter podľa <1>spôsobu úhrady</1> — hotovosť, karta, prevod. Tlačidlom <2>Stĺpce</2> si zvolíte, čo v tabuľke vidíte (napríklad kategóriu, základ, DPH či spôsob úhrady), a tlačidlom <3>Uložiť filter</3> si odložíte často používaný výber — záložku, mesiac, hľadaný text a úhradu. Uložené filtre potom vyberiete zo zoznamu <4>Uložené filtre</4>. Stĺpce aj filtre platia buď pre jednu firmu, alebo po zaškrtnutí <5>Pre všetky moje firmy</5> pre všetky naraz.":
    "Über der Liste finden Sie <0>Suchen</0> (Lieferant, Firmen-ID, Belegnummer) und einen Filter nach <1>Zahlungsart</1> — bar, Karte, Überweisung. Mit der Schaltfläche <2>Spalten</2> wählen Sie, was in der Tabelle angezeigt wird (zum Beispiel Kategorie, Bemessungsgrundlage, MwSt. oder Zahlungsart), und mit <3>Filter speichern</3> legen Sie eine häufig genutzte Auswahl ab — Reiter, Monat, Suchtext und Zahlungsart. Gespeicherte Filter wählen Sie dann aus der Liste <4>Gespeicherte Filter</4>. Spalten und Filter gelten entweder für ein Unternehmen oder, wenn Sie <5>Für alle meine Unternehmen</5> ankreuzen, für alle zugleich.",
  "Do balíka pre účtovníčku idú doklady spolu s faktúrami cez <0>Účtovné exporty</0>; ak účtujete v Pohode, prenesú sa aj tam — pozri <1>Prepojenie s Pohodou</1>.":
    "Ins Paket für die Buchhalterin gehen die Belege zusammen mit den Rechnungen über <0>Export an die Buchhaltung</0>; wenn Sie in Pohoda buchen, werden sie auch dorthin übertragen — siehe <1>Anbindung an Pohoda</1>.",
  "Najrýchlejšia cesta, ako dostať faktúru od dodávateľa dnu: nechať ju tam prísť samu. Každá firma má vlastnú adresu, napríklad <0>vasafirma-k7f2p9@doklady.faktero.sk</0>, a čo na ňu prepošlete, to sa spracuje.":
    "Der schnellste Weg, eine Lieferantenrechnung zu erfassen: Lassen Sie sie von selbst ankommen. Jedes Unternehmen hat eine eigene Adresse, zum Beispiel <0>vasafirma-k7f2p9@doklady.faktero.sk</0>, und was Sie dorthin weiterleiten, wird verarbeitet.",
  "Adresu nájdete v <0>Doklady → Doklady e-mailom</0>. Skopírujete ju a prepošlete na ňu mail od dodávateľa — nič sa nesťahuje a nikam sa neprihlasujete. Z PDF v prílohe sa prečíta dodávateľ, IČO, IČ DPH, IBAN, číslo faktúry, variabilný symbol, dátum vystavenia aj splatnosti, sumy a <1>jednotlivé položky</1> — tie sú na detaile dokladu len na prezretie, do skladu ani do účtovníctva nevstupujú.":
    "Die Adresse finden Sie unter <0>Belege → Belege per E-Mail</0>. Kopieren Sie sie und leiten Sie die E-Mail des Lieferanten dorthin weiter — nichts herunterladen, nirgends anmelden. Aus dem PDF im Anhang werden Lieferant, Firmen-ID, USt-IdNr., IBAN, Rechnungsnummer, Verwendungszweck (VS), Rechnungsdatum und Fälligkeit, Beträge sowie <1>die einzelnen Positionen</1> ausgelesen — diese sind im Belegdetail nur zur Ansicht und fließen weder ins Lager noch in die Buchhaltung ein.",
  "<0>Zdrojový e-mail.</0> Text mailu, s ktorým doklad prišiel („to je za september“, „zákazka Novák“), sa uloží. Ukážete ho ikonou obálky v Nespracovaných alebo tlačidlom <1>Zdrojový e-mail</1> pri doklade — aj po tom, čo z neho vznikla prijatá faktúra, bloček či iný doklad.":
    "<0>Ursprüngliche E-Mail.</0> Der Text der E-Mail, mit der der Beleg kam („das ist für September“, „Projekt Novák“), wird gespeichert. Sie zeigen ihn über das Briefumschlag-Symbol in den Unverarbeiteten oder mit der Schaltfläche <1>Ursprüngliche E-Mail</1> beim Beleg an — auch nachdem daraus eine Eingangsrechnung, ein Kassenbon oder ein sonstiger Beleg entstanden ist.",
  "Na detaile dokladu je aj <0>náhľad prílohy</0>, takže na prezretie nemusíte nič sťahovať.":
    "Im Belegdetail gibt es auch eine <0>Vorschau des Anhangs</0>, sodass Sie zum Ansehen nichts herunterladen müssen.",
  "Doklad potom čaká v <0>Nespracovaných dokladoch</0>. <1>Nič sa nezaeviduje samo</1> — určíte druh, skontrolujete, zaúčtujete a vytvoríte.":
    "Der Beleg wartet dann in den <0>Unverarbeiteten Belegen</0>. <1>Nichts wird automatisch erfasst</1> — Sie bestimmen die Art, prüfen, verbuchen und erstellen.",
  "Čo je dobré vedieť:": "Gut zu wissen:",
  "Adresa je pre <0>každú firmu iná</0>. Ak máte firiem viac, prepnite sa hore v lište a vezmite si tú správnu — alebo použite <1>rozdeľovač</1> (nižšie).":
    "Die Adresse ist für <0>jedes Unternehmen anders</0>. Wenn Sie mehrere Unternehmen haben, wechseln Sie oben in der Leiste und nehmen Sie die richtige — oder verwenden Sie den <1>Verteiler</1> (siehe unten).",
  "Viac príloh v jednom maile znamená <0>viac dokladov</0> — každá sa spracuje zvlášť, najviac však <1>15</1> z jedného e-mailu.":
    "Mehrere Anhänge in einer E-Mail bedeuten <0>mehrere Belege</0> — jeder wird einzeln verarbeitet, höchstens jedoch <1>15</1> aus einer E-Mail.",
  "Adresa sa dá <0>zmeniť na vlastnú</0> — tlačidlom „Zvoliť vlastnú“ si namiesto náhodného konca zadáte svoje slovo a číslo, napríklad <1>doklady-2026@doklady.faktero.sk</1>. Diakritiku, medzery a veľké písmená si Faktero opraví samo a hneď ukáže, ako bude adresa naozaj vyzerať.":
    "Die Adresse lässt sich <0>in eine eigene ändern</0> — mit der Schaltfläche „Eigene wählen“ geben Sie statt der zufälligen Endung Ihr eigenes Wort und eine Zahl ein, zum Beispiel <1>doklady-2026@doklady.faktero.sk</1>. Diakritik, Leerzeichen und Großbuchstaben korrigiert Faktero selbst und zeigt sofort, wie die Adresse tatsächlich aussehen wird.",
  "<0>Pozor, adresa je zároveň heslo.</0> Kto ju pozná, vie vám poslať doklad — preto sa predvolene generuje s náhodným koncom, ktorý sa nedá uhádnuť z názvu firmy. Krátku a logickú adresu si vie domyslieť aj cudzí človek. Ak vlastnú chcete, pridajte do nej niečo svoje, čo nie je na prvý pokus zrejmé.":
    "<0>Achtung, die Adresse ist zugleich ein Passwort.</0> Wer sie kennt, kann Ihnen einen Beleg schicken — deshalb wird sie standardmäßig mit einer zufälligen Endung erzeugt, die sich aus dem Firmennamen nicht erraten lässt. Eine kurze und logische Adresse kann auch ein Fremder erraten. Wenn Sie eine eigene möchten, fügen Sie etwas Persönliches hinzu, das nicht auf Anhieb offensichtlich ist.",
  "Na tej istej stránke je aj <0>denník posledných mailov</0> — pri každom vidno, ako dopadol. Keď doklad nedorazil, začnite tam. A keby sa adresa dostala tam, kam nemá, dá sa vypnúť alebo vymeniť za novú; stará vtedy prestane prijímať. Pri každom maile je aj <1>zobraziť e-mail</1> — text pôvodného mailu, napríklad keď dodávateľ do neho napísal niečo k platbe.":
    "Auf derselben Seite finden Sie auch das <0>Protokoll der letzten E-Mails</0> — bei jeder sehen Sie, wie sie verarbeitet wurde. Wenn ein Beleg nicht angekommen ist, beginnen Sie dort. Und sollte die Adresse in falsche Hände geraten, lässt sie sich deaktivieren oder durch eine neue ersetzen; die alte nimmt dann nichts mehr an. Bei jeder E-Mail gibt es auch <1>E-Mail anzeigen</1> — den Text der ursprünglichen E-Mail, etwa wenn der Lieferant darin etwas zur Zahlung geschrieben hat.",
  "<0>Povolení odosielatelia.</0> Na tej istej stránke môžete zapísať adresy alebo domény (napr. <1>@dodavatel.sk</1>), od ktorých sa doklady prijímajú — jednu na riadok. Mail od niekoho iného sa nezaloží a v denníku bude ako „Odmietnuté — nepovolený odosielateľ“. Prázdny zoznam znamená, že doklad prijme od kohokoľvek, kto adresu pozná.":
    "<0>Zugelassene Absender.</0> Auf derselben Seite können Sie Adressen oder Domains (z. B. <1>@dodavatel.sk</1>) eintragen, von denen Belege angenommen werden — eine pro Zeile. Eine E-Mail von jemand anderem wird nicht angelegt und erscheint im Protokoll als „Abgelehnt — nicht zugelassener Absender“. Eine leere Liste bedeutet, dass Belege von jedem angenommen werden, der die Adresse kennt.",
  "<0>Kontrola odberateľa.</0> Keď je na doklade iný odberateľ (iné IČO alebo IČ DPH) než vaša firma, doklad sa založí, ale s upozornením v poznámke aj v denníku mailov — aby sa vám medzi náklady nedostala cudzia faktúra.":
    "<0>Prüfung des Kunden.</0> Ist auf dem Beleg ein anderer Kunde (andere Firmen-ID oder USt-IdNr.) als Ihr Unternehmen angegeben, wird der Beleg angelegt, jedoch mit einem Hinweis in der Notiz und im E-Mail-Protokoll — damit keine fremde Rechnung unter Ihre Aufwendungen gerät.",
  "Automatické preposielanie z Gmailu": "Automatische Weiterleitung aus Gmail",
  "Prepošlite si doklady <0>raz a navždy</0>: Gmail vie posielať kópiu pošty na inú adresu sám. Nastavíte to v Gmaile v <1>Nastavenia → Preposielanie a POP/IMAP → Pridať adresu na preposielanie</1>, kam vložíte svoju adresu z <2>Doklady → Doklady e-mailom</2>.":
    "Leiten Sie Belege <0>ein für alle Mal</0> weiter: Gmail kann selbst eine Kopie der Post an eine andere Adresse senden. Sie richten das in Gmail unter <1>Einstellungen → Weiterleitung und POP/IMAP → Weiterleitungsadresse hinzufügen</1> ein und tragen dort Ihre Adresse aus <2>Belege → Belege per E-Mail</2> ein.",
  "Google si to musí overiť, a preto pošle <0>potvrdzovací mail</0> — lenže pošle ho na tú novú adresu, teda k nám. Preto ho <1>Faktero zachytí a ukáže vám ho</1>: na stránke Doklady e-mailom sa objaví žltý pruh „Google žiada potvrdenie preposielania“. Objaví sa sám, netreba obnovovať stránku.":
    "Google muss das überprüfen und sendet deshalb eine <0>Bestätigungs-E-Mail</0> — allerdings an die neue Adresse, also zu uns. Deshalb <1>fängt Faktero sie ab und zeigt sie Ihnen an</1>: Auf der Seite Belege per E-Mail erscheint ein gelber Balken „Google fordert eine Bestätigung der Weiterleitung an“. Er erscheint von selbst, die Seite muss nicht neu geladen werden.",
  "V pruhu je to, čo od vás Google chce:": "Im Balken steht, was Google von Ihnen möchte:",
  "tlačidlo <0>Potvrdiť preposielanie</0> — odkaz od Googlu. Funguje len v prehliadači, kde ste prihlásený do <1>tej istej</1> schránky;":
    "die Schaltfläche <0>Weiterleitung bestätigen</0> — der Link von Google. Er funktioniert nur in einem Browser, in dem Sie im <1>selben</1> Postfach angemeldet sind;",
  "<0>kód</0>, keď ho Google poslal — dá sa skopírovať a vložiť priamo v Gmaile vedľa tlačidla „Overiť“. Google ho ale posiela len niekedy, väčšinou príde iba odkaz;":
    "einen <0>Code</0>, falls Google einen gesendet hat — er lässt sich kopieren und direkt in Gmail neben der Schaltfläche „Bestätigen“ einfügen. Google sendet ihn aber nur manchmal, meist kommt nur der Link;",
  "tlačidlo <0>Už som potvrdil</0>, ktorým pruh odpracete — Google nám o potvrdení nedá vedieť, takže sám nezmizne.":
    "die Schaltfläche <0>Bereits bestätigt</0>, mit der Sie den Balken ausblenden — Google teilt uns die Bestätigung nicht mit, daher verschwindet er nicht von selbst.",
  "Potom sa vráťte do Gmailu, zapnite <0>„Preposielať kópiu doručenej pošty na…“</0> a uložte. Samotné overenie preposielanie ešte nezapne.":
    "Kehren Sie dann zu Gmail zurück, aktivieren Sie <0>„Eine Kopie eingehender E-Mails weiterleiten an…“</0> und speichern Sie. Die Bestätigung allein schaltet die Weiterleitung noch nicht ein.",
  "<0>Odporúčame nepreposielať všetko.</0> V Gmaile si radšej spravte filter (<1>Vyhľadávanie → Vytvoriť filter → Preposlať na</1>) napríklad na maily s prílohou alebo na konkrétnych dodávateľov. Inak sa Faktero pokúsi spraviť doklad z každého mailu, čo vám príde, a denník sa zaplní hláškami „bez prílohy“.":
    "<0>Wir empfehlen, nicht alles weiterzuleiten.</0> Legen Sie in Gmail lieber einen Filter an (<1>Suche → Filter erstellen → Weiterleiten an</1>), zum Beispiel für E-Mails mit Anhang oder für bestimmte Lieferanten. Sonst versucht Faktero, aus jeder eingehenden E-Mail einen Beleg zu machen, und das Protokoll füllt sich mit Meldungen „ohne Anhang“.",
  "Potvrdenie platí <0>sedem dní</0>. Keď ho prešvihnete, jednoducho pridajte adresu v Gmaile znova — príde nové.":
    "Die Bestätigung ist <0>sieben Tage</0> gültig. Wenn Sie sie verpassen, fügen Sie die Adresse in Gmail einfach erneut hinzu — es kommt eine neue.",
  "<0>Prečo je to bezpečné.</0> Potvrdzovací mail prijmeme len od skutočnej adresy Googlu a len vtedy, keď sedí jeho elektronický podpis (SPF a DKIM domény <1>google.com</1>). Podvrhnutý mail „od Googlu“ s cudzím odkazom zahodíme. Z mailu si navyše necháme iba kód, odkaz a adresu schránky, z ktorej sa preposiela — <2>obsah mailu sa nikam neukladá</2>.":
    "<0>Warum das sicher ist.</0> Die Bestätigungs-E-Mail nehmen wir nur von einer echten Google-Adresse an und nur dann, wenn ihre elektronische Signatur stimmt (SPF und DKIM der Domain <1>google.com</1>). Eine gefälschte E-Mail „von Google“ mit fremdem Link verwerfen wir. Außerdem behalten wir aus der E-Mail nur den Code, den Link und die Adresse des weiterleitenden Postfachs — <2>der Inhalt der E-Mail wird nirgends gespeichert</2>.",
  "V telefóne": "Auf dem Smartphone",
  "Skenovanie je hlavný dôvod, prečo mať Faktero v telefóne — bloček odfotíte hneď pri pokladni a nemusíte ho nosiť domov. Funguje to <0>aj bez signálu</0>: doklad sa uloží do telefónu a odošle sa, keď sa pripojíte.":
    "Das Scannen ist der Hauptgrund, Faktero auf dem Smartphone zu haben — den Kassenbon fotografieren Sie gleich an der Kasse und müssen ihn nicht nach Hause tragen. Das funktioniert <0>auch ohne Empfang</0>: Der Beleg wird auf dem Telefon gespeichert und gesendet, sobald Sie wieder verbunden sind.",
  "Faktúru z PDF viete rovnakým spôsobom načítať aj v <0>Skeneri dokladov</0> na webe.":
    "Eine Rechnung als PDF können Sie auf dieselbe Weise auch im <0>Belegscanner</0> im Web einlesen.",
  "Odpočet DPH z bločkov": "Vorsteuerabzug aus Kassenbons",
  "Bloček je zjednodušená faktúra — do kontrolného výkazu ide do časti <0>B.3</0>, nie medzi bežné prijaté faktúry. Do 3 000 € odpočítanej dane za obdobie sa vykazuje sumárne, nad túto hranicu sa rozpisuje po dodávateľoch (vtedy je potrebné IČ DPH dodávateľa).":
    "Ein Kassenbon ist eine vereinfachte Rechnung — in der Kontrollmeldung (KV DPH) gehört er in Teil <0>B.3</0>, nicht zu den gewöhnlichen Eingangsrechnungen. Bis 3 000 € abgezogener Steuer pro Zeitraum wird er summarisch gemeldet, über dieser Grenze nach Lieferanten aufgeschlüsselt (dann ist die USt-IdNr. des Lieferanten erforderlich).",
  "Keď si z dokladu daň neodpočítavate, prepnite na ňom <0>Odpočítanie dane</0> — do výkazu potom nevstúpi.":
    "Wenn Sie die Steuer aus einem Beleg nicht abziehen, schalten Sie bei ihm <0>Vorsteuerabzug</0> um — dann fließt er nicht in die Meldung ein.",
  "V <0>Nastavenia → Schvaľovanie dokladov</0> zapnete, ktoré doklady sa schvaľujú (bločky, prijaté, vystavené faktúry), sumu, pod ktorou sa schvália samy, a či sa vystavená faktúra smie odoslať až po schválení. Platí to pre doklady pridané od zapnutia.":
    "Unter <0>Einstellungen → Belegfreigabe</0> legen Sie fest, welche Belege freigegeben werden müssen (Kassenbons, Eingangs-, Ausgangsrechnungen), den Betrag, unter dem sie automatisch freigegeben werden, und ob eine Ausgangsrechnung erst nach der Freigabe gesendet werden darf. Das gilt für Belege, die nach dem Aktivieren hinzugefügt wurden.",
  "<0>Schvaľovacia cesta</0> má úrovne od najnižšej po najvyššiu, v každej jedného alebo viac schvaľovateľov. Schválenie vyššou úrovňou platí aj za nižšie. Pravidlá cesty (dodávateľ podľa IČO, suma od, predkontácia, druh dokladu) určia, ktorá cesta sa použije; inak predvolená. Bez ciest stačí jedno schválenie majiteľom, správcom alebo účtovníkom.":
    "Ein <0>Freigabeweg</0> hat Stufen von der niedrigsten bis zur höchsten, in jeder einen oder mehrere Freigebende. Eine Freigabe auf höherer Stufe gilt auch für die niedrigeren. Regeln des Freigabewegs (Lieferant nach Firmen-ID, Betrag ab, Vorkontierung, Belegart) bestimmen, welcher Weg verwendet wird; sonst der Standardweg. Ohne Freigabewege genügt eine Freigabe durch Inhaber, Administrator oder Buchhalter.",
  "Do úrovne cesty sa dá namiesto konkrétneho človeka vybrať <0>manažér zákazky dokladu</0> (projektový manažér). Doklad zaradený na zákazku potom schvaľuje jej manažér — ten sa nastavuje na detaile <1>zákazky</1>. Keď doklad na zákazke nie je alebo zákazka manažéra nemá, táto úroveň sa preskočí.":
    "In eine Stufe des Freigabewegs lässt sich statt einer bestimmten Person der <0>Projektmanager des Belegs</0> wählen. Einen einem Projekt zugeordneten Beleg gibt dann dessen Manager frei — dieser wird im Detail des <1>Projekts</1> festgelegt. Ist der Beleg keinem Projekt zugeordnet oder hat das Projekt keinen Manager, wird diese Stufe übersprungen.",
  "Doklady čakajúce na vás sú v <0>Doklady → Na schválenie</0> aj v zvončeku; schváliť, vrátiť na opravu či zamietnuť ich viete hromadne aj na detaile dokladu. Do Pohody, do mesačného balíka a do príkazu na úhradu idú len schválené. Vrátený doklad sa po oprave vráti na schválenie odznova.":
    "Belege, die auf Sie warten, finden Sie unter <0>Belege → Zur Freigabe</0> und in der Glocke; freigeben, zur Korrektur zurückgeben oder ablehnen können Sie sie gesammelt oder im Belegdetail. An Pohoda, ins Monatspaket und in den Zahlungsauftrag gehen nur freigegebene Belege. Ein zurückgegebener Beleg geht nach der Korrektur erneut in die Freigabe.",
  "<0>Moje úlohy</0> (v menu hneď pod Prehľadom, s počtom) zhrnú na jednej stránke všetko, čo čaká práve na vás: doklady na vaše schválenie, komentáre, v ktorých vás kolega označil, a nespracované doklady na kontrolu. Komentár po vybavení označte tlačidlom <1>Vyriešiť</1> — zmizne z vašich úloh aj zo zvončeka. Keď komentár označil viacerých kolegov, každý ho rieši za seba. Na stránku sa dostanete aj zo zvončeka cez <2>Všetky moje úlohy</2>.":
    "<0>Meine Aufgaben</0> (im Menü direkt unter der Übersicht, mit Anzahl) fassen auf einer Seite alles zusammen, was gerade auf Sie wartet: Belege zu Ihrer Freigabe, Kommentare, in denen ein Kollege Sie erwähnt hat, und unverarbeitete Belege zur Prüfung. Markieren Sie einen erledigten Kommentar mit der Schaltfläche <1>Erledigen</1> — er verschwindet aus Ihren Aufgaben und aus der Glocke. Wurden in einem Kommentar mehrere Kollegen erwähnt, erledigt ihn jeder für sich. Zur Seite gelangen Sie auch über die Glocke unter <2>Alle meine Aufgaben</2>.",
  "Vyúčtovanie výdavkov zamestnanca": "Spesenabrechnung von Mitarbeitern",
  "Bločky a faktúry, ktoré zaplatil zamestnanec, zhrnie <0>Doklady → Vyúčtovanie výdavkov</0>. Vyúčtovanie má tri typy: <1>poskytnutá záloha</1> (rozdiel sa doplatí alebo vráti), <2>vlastné zdroje zamestnanca</2> (firma preplatí celú sumu) a <3>firemná debetná karta</3> (nič sa nedopláca, zamestnanec len preukazuje výdavky).":
    "Kassenbons und Rechnungen, die ein Mitarbeiter bezahlt hat, fasst <0>Belege → Spesenabrechnung</0> zusammen. Die Abrechnung hat drei Arten: <1>gewährter Vorschuss</1> (die Differenz wird nachgezahlt oder erstattet), <2>eigene Mittel des Mitarbeiters</2> (das Unternehmen erstattet den gesamten Betrag) und <3>Firmen-Debitkarte</3> (es wird nichts nachgezahlt, der Mitarbeiter weist nur die Ausgaben nach).",
  "Najrýchlejšie: v Bločkoch alebo Prijatých faktúrach označte doklady a kliknite na <0>Vyúčtovanie</0> — vytvoríte nové alebo pridáte do existujúceho.":
    "Am schnellsten: Markieren Sie in den Kassenbons oder Eingangsrechnungen die Belege und klicken Sie auf <0>Abrechnung</0> — Sie erstellen eine neue oder fügen sie einer bestehenden hinzu.",
  "Výsledok („Firma doplatí zamestnancovi 166,50 EUR“) a <0>PDF na podpis</0> zamestnanca a schvaľujúceho.":
    "Das Ergebnis („Das Unternehmen zahlt dem Mitarbeiter 166,50 EUR nach“) und ein <0>PDF zur Unterschrift</0> durch Mitarbeiter und Freigebenden.",
  "Účtovné nastavenia vyúčtovania (predkontácia, členenie DPH, dátum účtovania) sa doplnia dokladom, ktoré ich ešte nemajú.":
    "Die buchhalterischen Einstellungen der Abrechnung (Vorkontierung, MwSt.-Kennzeichen, Buchungsdatum) werden bei Belegen ergänzt, die sie noch nicht haben.",
  "Bloček vo vyúčtovaní ide do Pohody ako <0>interný doklad</0>, nie ako výdaj z firemnej pokladne. Prijatú faktúru vo vyúčtovaní hromadný príkaz na úhradu vynechá — dodávateľa už zaplatil zamestnanec.":
    "Ein Kassenbon in der Abrechnung geht als <0>interner Beleg</0> an Pohoda, nicht als Ausgabe aus der Firmenkasse. Eine Eingangsrechnung in der Abrechnung lässt der Sammelzahlungsauftrag aus — den Lieferanten hat bereits der Mitarbeiter bezahlt.",
  "Doklad môže byť len v jednom vyúčtovaní. Uzavreté vyúčtovanie sa dá znova otvoriť.":
    "Ein Beleg kann nur in einer Abrechnung enthalten sein. Eine abgeschlossene Abrechnung lässt sich wieder öffnen.",
  "Kôš, komentáre a poznámky": "Papierkorb, Kommentare und Notizen",
  "Zmazaný doklad ide do <0>koša</0> (tlačidlo Kôš v Dokladoch). Do 90 dní sa dá obnoviť aj s párovaním na pohyb v banke, potom sa kôš vysype sám aj so skenom.":
    "Ein gelöschter Beleg kommt in den <0>Papierkorb</0> (Schaltfläche Papierkorb in den Belegen). Innerhalb von 90 Tagen lässt er sich samt Abgleich mit der Bankbewegung wiederherstellen, danach leert sich der Papierkorb von selbst, einschließlich des Scans.",
  "Na detaile dokladu sú <0>komentáre</0> — otázka účtovníčke, vysvetlenie výdavku. Označený kolega dostane upozornenie do zvončeka.":
    "Im Belegdetail gibt es <0>Kommentare</0> — eine Frage an die Buchhalterin, eine Erläuterung der Ausgabe. Ein erwähnter Kollege erhält eine Benachrichtigung in der Glocke.",
  "Pri poznámke si viete opakované texty uložiť ako <0>preddefinované</0> a potom ich len vyberať.":
    "Bei Notizen können Sie wiederkehrende Texte als <0>Vorlagen</0> speichern und dann nur noch auswählen.",
  "<0>Prílohy a presun.</0> K dokladu sa dá priložiť ďalší súbor (dodací list, druhá strana). Keď sa druhá strana či dodací list nahrali ako saminý doklad, tlačidlom <1>Presunúť ako prílohu</1> ho pripojíte k správnemu dokladu, prijatej či vystavenej faktúre — pôvodný záznam ide do koša.":
    "<0>Anhänge und Verschieben.</0> Einem Beleg lässt sich eine weitere Datei anhängen (Lieferschein, zweite Seite). Wurde die zweite Seite oder der Lieferschein als eigener Beleg hochgeladen, hängen Sie ihn mit der Schaltfläche <1>Als Anhang verschieben</1> an den richtigen Beleg, die Eingangs- oder Ausgangsrechnung an — der ursprüngliche Eintrag kommt in den Papierkorb.",
  "<0>Pravidlo účtovania</0> doplní kódy samo; doklad, ktorý ich má z pravidla, má pri zaúčtovaní hviezdičku. Keď má dodávateľ pravidiel viac, vyberiete iné cez <1>Použiť pravidlo</1>. Zoznam sa dá zoradiť kliknutím na hlavičku stĺpca a stiahnuť do Excelu.":
    "Eine <0>Buchungsregel</0> ergänzt die Codes selbst; ein Beleg, der sie aus einer Regel hat, trägt bei der Kontierung ein Sternchen. Hat ein Lieferant mehrere Regeln, wählen Sie über <1>Regel anwenden</1> eine andere. Die Liste lässt sich per Klick auf die Spaltenüberschrift sortieren und nach Excel herunterladen.",
  "Odovzdaný doklad je <0>zamknutý</0> — jeho sumy, dátumy ani zaúčtovanie sa nedajú zmeniť, kým ho nevrátite z Pohody.":
    "Ein übergebener Beleg ist <0>gesperrt</0> — Beträge, Daten und Kontierung lassen sich nicht ändern, bis Sie ihn aus Pohoda zurückholen.",
  "Voľba <0>Automaticky určiť typ faktúry podľa firemných IBAN-ov</0>: keď je na faktúre ako príjemca platby IBAN niektorého vášho bankového účtu, je to vaša vystavená faktúra. Faktero ju výrazne označí, ponúkne uložiť ju ako iný doklad alebo zmazať a medzi prijaté ju založí len po potvrdení. V <1>Predponách čísla objednávky</1> zadáte, ako začínajú čísla vašich objednávok (napr. OBJ-, PO) — také číslo sa pri vyťažení zapíše do poľa Číslo objednávky.":
    "Die Option <0>Rechnungstyp automatisch anhand der Firmen-IBANs bestimmen</0>: Steht auf der Rechnung als Zahlungsempfänger die IBAN eines Ihrer Bankkonten, ist es Ihre ausgestellte Rechnung. Faktero markiert sie deutlich, bietet an, sie als anderen Beleg zu speichern oder zu löschen, und legt sie nur nach Bestätigung als Eingangsrechnung an. Unter <1>Präfixe der Bestellnummer</1> geben Sie an, womit Ihre Bestellnummern beginnen (z. B. OBJ-, PO) — eine solche Nummer wird beim Auslesen in das Feld Bestellnummer eingetragen.",
  "V náhľade PDF sú <0>modrým rámčekom</0> vyznačené miesta, odkiaľ sa vzali číslo faktúry, VS, IBAN, IČO, DIČ, IČ DPH, dátumy a suma. Keď kliknete do poľa, jeho miesto sa zvýrazní silnejšie a náhľad sa naň posunie. Zvýraznenie vypnete ikonou zvýrazňovača nad náhľadom. Pri fotkách a skenoch bez textu sa nič nevyznačí.":
    "In der PDF-Vorschau sind mit einem <0>blauen Rahmen</0> die Stellen markiert, aus denen Rechnungsnummer, VS, IBAN, IČO, DIČ, USt-IdNr., Daten und Betrag stammen. Wenn Sie in ein Feld klicken, wird seine Stelle stärker hervorgehoben und die Vorschau springt dorthin. Die Hervorhebung schalten Sie mit dem Textmarker-Symbol über der Vorschau aus. Bei Fotos und Scans ohne Text wird nichts markiert.",
  "<0>Ukladať aj e-maily bez dokladu.</0> Keď mail nemá PDF ani fotku dokladu (faktúra je priamo v texte alebo len odkaz na stiahnutie), predvolene ostane len v zozname posledných mailov. Po zaškrtnutí tejto voľby sa uloží do Nespracovaných ako PDF s textom mailu a spracujete ho ako každý iný doklad.":
    "<0>Auch E-Mails ohne Beleg speichern.</0> Hat eine E-Mail weder PDF noch Foto eines Belegs (die Rechnung steht direkt im Text oder es gibt nur einen Download-Link), bleibt sie standardmäßig nur in der Liste der letzten E-Mails. Mit dieser Option wird sie als PDF mit dem E-Mail-Text in Unverarbeitete gespeichert und Sie bearbeiten sie wie jeden anderen Beleg.",
  "Pri poznámke si viete opakované texty uložiť ako <0>preddefinované</0> a potom ich len vyberať. Číselník je v <1>Nastavenia → Preddefinované poznámky</1> (alebo cez „Spravovať poznámky…“ priamo pri poli): každá poznámka má názov, text a agendy, kde sa ponúka — vystavené a prijaté faktúry, bločky, Nespracované.":
    "Wiederkehrende Texte können Sie bei der Notiz als <0>vordefiniert</0> speichern und dann nur auswählen. Die Liste finden Sie unter <1>Einstellungen → Vordefinierte Notizen</1> (oder über „Notizen verwalten…“ direkt beim Feld): Jede Notiz hat einen Namen, einen Text und die Bereiche, in denen sie angeboten wird — ausgestellte und Eingangsrechnungen, Kassenbelege, Unverarbeitete.",
  "V zoznamoch bločkov, prijatých a vystavených faktúr vyberiete <0>účtovnú položku</0> (predkontáciu) priamo v riadku, s hľadaním. Po označení viacerých dokladov — aj v Iných dokladoch — ponúkne <1>Hromadná akcia</1> účtovnú položku, typ platby, členenie DPH a KV, účtovnú poznámku, komentár, vlastný stav, štítky aj označenie úhrady. Odovzdané, zamknuté doklady a doklady v uzavretom období sa pri účtovných zmenách preskočia. Vlastné <2>stavy dokladov</2> (napr. „Čaká na doklad od klienta“) a štítky si nastavíte v Účtovníctvo → Predkontácie; <3>komentár</3> sa na rozdiel od účtovnej poznámky do účtovníctva nikdy neprenáša.":
    "In den Listen der Kassenbelege, Eingangs- und Ausgangsrechnungen wählen Sie die <0>Buchungsposition</0> (Vorkontierung) direkt in der Zeile, mit Suche. Nach dem Markieren mehrerer Belege — auch bei Sonstigen Belegen — bietet die <1>Sammelaktion</1> Buchungsposition, Zahlungsart, USt- und KV-Gliederung, Buchungsnotiz, Kommentar, eigenen Status, Etiketten und die Zahlungsmarkierung an. Übergebene, gesperrte Belege und Belege in einem abgeschlossenen Zeitraum werden bei buchhalterischen Änderungen übersprungen. Eigene <2>Belegstatus</2> (z. B. „Wartet auf Beleg vom Kunden“) und Etiketten legen Sie unter Buchhaltung → Vorkontierungen fest; der <3>Kommentar</3> wird im Unterschied zur Buchungsnotiz nie in die Buchhaltung übertragen.",
  "Pri výbere sa pod zoznamom ukáže <0>súčtová lišta</0> — počet dokladov, suma s DPH aj bez DPH a koľko z toho čaká na export a na úhradu (podrobnejšie v manuáli <1>Prijaté faktúry</1>). Na detaile bločku, prijatej aj vystavenej faktúry sa šípkami <2>Predošlý doklad</2> a <3>Ďalší doklad</3> posuniete na susedný doklad bez návratu do zoznamu.":
    "Bei einer Auswahl erscheint unter der Liste die <0>Summenleiste</0> — Anzahl der Belege, Betrag mit und ohne USt und wie viel davon auf den Export und auf die Zahlung wartet (ausführlicher im Handbuch <1>Eingangsrechnungen</1>). Im Detail eines Kassenbelegs, einer Eingangs- oder Ausgangsrechnung wechseln Sie mit den Pfeilen <2>Vorheriger Beleg</2> und <3>Nächster Beleg</3> zum benachbarten Beleg, ohne zur Liste zurückzukehren.",
  "Berie sa <0>PDF alebo fotka</0> v prílohe. Mail bez prílohy sa v denníku označí ako „bez prílohy“ a nič sa nezaloží — ak nemáte zapnuté <1>Ukladať aj e-maily bez dokladu</1> (nižšie).":
    "Verarbeitet wird ein <0>PDF oder Foto</0> im Anhang. Eine E-Mail ohne Anhang wird im Protokoll als „ohne Anhang“ markiert und es wird nichts angelegt — außer Sie haben <1>Auch E-Mails ohne Beleg speichern</1> eingeschaltet (unten).",
  "<0>Rozdeľovač — jedna adresa pre všetky firmy.</0> Kto vedie viac firiem (alebo účtovníčka s klientmi), nemusí si pamätať adresu každej. V karte <1>Rozdeľovač</1> na tej istej stránke je vaša osobná adresa v tvare <2>rozdelovac-…@doklady.faktero.sk</2>. Faktero z každej prílohy prečíta odberateľa — IČO, IČ DPH a DIČ; až keď na doklade nie sú, IBAN platiteľa alebo názov — a doklad pošle do <3>Nespracovaných</3> tej z vašich firiem, na ktorú je vystavený, s poznámkou, podľa čoho ho zaradil. Jeden mail tak môže rozdeliť faktúry aj medzi viac firiem. Vyberá sa len z firiem, v ktorých smiete upravovať doklady, a firma, ktorá doklad sama vystavila, sa za odberateľa nepovažuje. Doklad, ktorý nesedí na žiadnu vašu firmu, sedí na viac firiem alebo si jeho údaje odporujú, sa naslepo nezaradí: počká v zozname <4>Nepriradené doklady</4> (firmy, na ktoré sedí, sú vo výbere označené hviezdičkou), kde vyberiete firmu a kliknete na <5>Priradiť</5>, prípadne <6>Zahodiť</6>. Rozdeľovač sa dá vypnúť a adresa vymeniť za novú. Potvrdenie preposielania z Gmailu treba nastaviť na adresu konkrétnej firmy, nie na rozdeľovač.":
    "<0>Verteiler — eine Adresse für alle Firmen.</0> Wer mehrere Firmen führt (oder eine Buchhalterin mit Mandanten), muss sich nicht die Adresse jeder einzelnen merken. In der Karte <1>Verteiler</1> auf derselben Seite steht Ihre persönliche Adresse in der Form <2>rozdelovac-…@doklady.faktero.sk</2>. Faktero liest aus jedem Anhang den Empfänger — IČO, USt-IdNr. und DIČ; erst wenn sie auf dem Beleg fehlen, die IBAN des Zahlers oder den Namen — und schickt den Beleg in die <3>Unverarbeiteten</3> derjenigen Ihrer Firmen, auf die er ausgestellt ist, mit einer Notiz, wonach er zugeordnet wurde. Eine E-Mail kann so Rechnungen auch auf mehrere Firmen verteilen. Gewählt wird nur aus Firmen, in denen Sie Belege bearbeiten dürfen, und die Firma, die den Beleg selbst ausgestellt hat, gilt nicht als Empfänger. Ein Beleg, der zu keiner Ihrer Firmen passt, zu mehreren passt oder dessen Angaben sich widersprechen, wird nicht blind zugeordnet: Er wartet in der Liste <4>Nicht zugeordnete Belege</4> (passende Firmen sind in der Auswahl mit einem Stern markiert), wo Sie die Firma wählen und auf <5>Zuordnen</5> oder <6>Verwerfen</6> klicken. Der Verteiler lässt sich ausschalten und die Adresse durch eine neue ersetzen. Die Weiterleitungsbestätigung von Gmail muss auf die Adresse einer konkreten Firma eingerichtet werden, nicht auf den Verteiler.",
  "<0>Nahrať do ktorejkoľvek firmy.</0> Rozdeľovač je aj v <1>Správe firiem</1> a ukáže sa každému, kto má prístup aspoň k dvom firmám. Tlačidlom <2>Nahrať do ktorejkoľvek firmy</2> vyberiete PDF alebo fotky dokladov (do 15 MB) bez prepínania firiem; firmu Faktero určí rovnako ako pri maile.":
    "<0>In eine beliebige Firma hochladen.</0> Den Verteiler gibt es auch in der <1>Firmenverwaltung</1>; er wird jedem angezeigt, der Zugriff auf mindestens zwei Firmen hat. Mit der Schaltfläche <2>In eine beliebige Firma hochladen</2> wählen Sie PDFs oder Fotos von Belegen (bis 15 MB), ohne die Firma zu wechseln; die Firma bestimmt Faktero genauso wie bei der E-Mail.",
  "Schvaľovať sa dajú aj <0>nespracované doklady</0> (bloček či faktúra z nich vznikne až po schválení) a <1>vyúčtovanie výdavkov</1> (schvaľuje sa po uzavretí). V tabuľke <2>Povolenia používateľov</2> nastavíte každému zvlášť Schvaľovanie, Zrušenie schválenia, Vrátenie a Zamietnutie; majiteľ má vždy všetko. Keď je zapnuté odoslanie až po schválení, neschválenú vystavenú faktúru server neodošle ani z appky, ani cez API.":
    "Genehmigen lassen sich auch <0>unverarbeitete Belege</0> (Kassenbeleg oder Rechnung entsteht daraus erst nach der Genehmigung) und die <1>Auslagenabrechnung</1> (wird nach dem Abschluss genehmigt). In der Tabelle <2>Benutzerberechtigungen</2> legen Sie für jeden einzeln Genehmigen, Genehmigung aufheben, Zurückgeben und Ablehnen fest; der Inhaber darf immer alles. Ist der Versand erst nach Genehmigung eingeschaltet, versendet der Server eine nicht genehmigte Ausgangsrechnung weder aus der App noch über die API.",
} satisfies Record<string, string>;
